			float m_sun_size=cos(directional_lights.data[0].color_size.w);
			if ((m_sun_angle > m_sun_size))
			{
							{
				m_sky=(directional_lights.data[0].color_size.xyz * directional_lights.data[0].direction_energy.w);
			}
;
			}
			else
			{
				if ((m_sun_angle > m_sun_angle_max))
				{
									{
