		}
;
		}
		if (bool(directional_lights.data[1].enabled_bake_mode & DIRECTIONAL_LIGHT_ENABLED))
		{
					{
			float m_sun_angle=dot(directional_lights.data[1].direction_energy.xyz, cube_normal);
			float m_sun_size=cos(directional_lights.data[1].color_size.w);
			if ((m_sun_angle > m_sun_size))
