		if (bool(directional_lights.data[2].enabled_bake_mode & DIRECTIONAL_LIGHT_ENABLED))
		{
					{
			float m_sun_angle=dot(directional_lights.data[2].direction_energy.xyz, cube_normal);
			float m_sun_size=cos(directional_lights.data[2].color_size.w);
			if ((m_sun_angle > m_sun_size))
			{
							{
				m_sky=(directional_lights.data[2].color_size.xyz * directional_lights.data[2].direction_energy.w);
