			}
;
			}
			else
			{
				if ((m_sun_angle > m_sun_angle_max))
				{
									{
					float m_c2=((m_sun_size - m_sun_angle) / (m_sun_size - m_sun_angle_max));
					m_sky=mix(m_sky, (directional_lights.data[3].color_size.xyz * directional_lights.data[3].direction_energy.w), clamp(pow((1.0 - m_c2), m_inv_sun_curve), 0.0, 1.0));
				}
;
				}
			}
		}
;
		}
		vec3 m_ground=mix(m_ground_bottom_color.rgb, m_ground_horizon_color.rgb, clamp(pow((1.0 + m_v_angle), m_inv_ground_curve), 0.0, 1.0));
		color=(mix(m_ground, m_sky, step(0.0, cube_normal.y)) * m_exposure);
